let data=load(),token='',driveFileId='',driveAttachmentFolderId='',organizationDriveFolderId=localStorage.getItem('so-xe-org-folder-id')||'',dirty=localStorage.getItem(DIRTY_KEY)==='1',driveEnabled=localStorage.getItem(DRIVE_ENABLED_KEY)==='1',syncRunning=false,syncAgain=false,tokenClient=null,autoConnectTimer=null,googleWaitCount=0;
