function confirmLargeOdo(odo,base,plate){const jump=Number(odo)-Number(base||0),unusuallyHigh=!base&&Number(odo)>1000000;if(jump<=ODO_JUMP_WARNING_KM&&!unusuallyHigh)return true;const comparison=base?`ODO tham chiếu hiện tại là ${Number(base).toLocaleString('vi-VN')} km, tăng ${jump.toLocaleString('vi-VN')} km.`:'Xe chưa có ODO tham chiếu.';return confirm(`Cảnh báo ODO có thể đã nhập quá lớn!\n\nXe ${plate||''}: ${Number(odo).toLocaleString('vi-VN')} km.\n${comparison}\n\nVui lòng kiểm tra xem có nhập thừa chữ số không. Vẫn lưu số ODO này?`)}
