function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function expenseTypeLabel(type){return type==='fuel'?'Đổ xăng':type==='charge'?'Sạc xe':type==='batteryRental'?'Thuê pin':type==='maintenance'?'Bảo dưỡng':type==='parts'?'Phụ tùng':type==='insurance'?'Bảo hiểm TNDS':type==='registration'?'Đăng kiểm':type==='roadFee'?'Phí đường bộ':'Chi phí khác'}
