function attachmentsOf(x){return Array.isArray(x?.attachments)?x.attachments.filter(a=>a&&a.driveFileId):[]}
function expenseDetailAction(x){const id=String(x.id||'');return /^[A-Za-z0-9_-]+$/.test(id)?`role="button" tabindex="0" aria-label="Xem chi tiết giao dịch" onclick="showExpenseDetail('${id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();showExpenseDetail('${id}')}"`:''}
