function vehicleAttachmentName(rec,file,index,count){const ext=(file.name||'').split('.').pop().replace(/[^a-zA-Z0-9]/g,'').slice(0,10);return String(rec.plate||'XE').replace(/[\\/:*?"<>|]/g,'-')+' - Giấy chủ quyền'+(count>1?' - '+(index+1):'')+(ext?'.'+ext:'')}
function attachmentName(rec,file,index,count){const c=car(rec.carId),clean=s=>String(s||'').replace(/[\\/:*?"<>|]/g,'-').replace(/\s+/g,' ').trim(),original=file.name||'',dot=original.lastIndexOf('.'),ext=dot>0?original.slice(dot+1).replace(/[^a-zA-Z0-9]/g,'').slice(0,10):'',suffix=count>1?' - '+(index+1):'';return `${clean(c?.plate||'XE')} - ${clean(expenseTypeLabel(rec.type))} - ${(rec.date||today()).replaceAll('-','')}${suffix}${ext?'.'+ext:''}`}
