function renderExistingAttachments(x,vehicle=false){const items=attachmentsOf(x),target=vehicle?'#existingCarAttachments':'#existingAttachments';document.querySelector(target).innerHTML=items.length?'<small>Tệp đã lưu trên Google Drive</small>'+attachmentItemsHtml(items,x.id):''}
