function canUploadAttachments(){if(!navigator.onLine){alert('Cần kết nối Internet để tải tệp đính kèm lên Google Drive. Giao dịch chưa được lưu.');return false}if(window.AndroidDrive){try{if(window.AndroidDrive.hasDriveToken())return true}catch{}alert('Hãy vào Cài đặt, kết nối Google Drive và chờ đồng bộ xong trước khi đính kèm tệp.');return false}if(typeof token==='undefined'||!token){alert('Hãy kết nối Google Drive trước khi đính kèm tệp.');return false}return true}
function fileToBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(new Error('Không đọc được tệp '+file.name));reader.readAsDataURL(file)})}
