window.openAttachment=async fileId=>{if(!window.orgCurrentUser?.())return;const record=[...data.expenses.filter(x=>window.orgCanViewExpense?.(x)),...visibleCars()].flatMap(x=>attachmentsOf(x)).find(a=>a.driveFileId===fileId);if(!record)return;try{if(!record.encryption)throw new Error('Tệp cũ chưa mã hóa; Admin cần chuyển đổi trước khi xem.');const r=await driveFetch('https://www.googleapis.com/drive/v3/files/'+encodeURIComponent(fileId)+'?alt=media',{headers:driveHeaders()});if(!r.ok)throw new Error('Không tải được tệp đính kèm');const plain=await OrgCrypto.decryptFile(await r.blob(),record.encryption),url=URL.createObjectURL(new Blob([plain],{type:record.mimeType||'application/octet-stream'})),a=document.createElement('a');a.href=url;a.download=record.originalName||record.name||'tep-dinh-kem';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(error){toast(error.message)}};
async function deleteDriveAttachment(fileId){const response=await driveFetch('https://www.googleapis.com/drive/v3/files/'+encodeURIComponent(fileId),{method:'DELETE',headers:driveHeaders()});if(!response.ok&&response.status!==404)throw new Error('Không xóa được tệp trên Google Drive (mã '+response.status+').')}
let attachmentDeletionBusy=false;
