window.deleteExistingAttachment=async(expenseId,fileId)=>{const expense=data.expenses.find(x=>x.id===expenseId)||data.cars.find(x=>x.id===expenseId),attachment=attachmentsOf(expense).find(a=>a.driveFileId===fileId);if(!window.orgCanWrite?.()||(data.cars.includes(expense)?!window.orgIsAdmin?.():!window.orgCanEditExpense?.(expense))||!attachment||attachmentDeletionBusy)return;if(!confirm('Xóa tệp "'+(attachment.name||'Tệp đính kèm')+'" khỏi Google Drive?'))return;attachmentDeletionBusy=true;try{if(!canUploadAttachments())return;await deleteDriveAttachment(fileId);const current=data.expenses.find(x=>x.id===expenseId)||data.cars.find(x=>x.id===expenseId);if(current){current.attachments=attachmentsOf(current).filter(a=>a.driveFileId!==fileId);persist();render();autoSyncNow();if(document.querySelector('#expenseId').value===expenseId){renderExistingAttachments(current);updateSelectedAttachments()}if(document.querySelector('#carId').value===expenseId){renderExistingAttachments(current,true);updateSelectedAttachments(true)}}toast('Đã xóa tệp đính kèm trên Google Drive')}catch(error){toast(error.message||'Không xóa được tệp đính kèm')}finally{attachmentDeletionBusy=false}};

function updateExpenseTypeOptions(){const c=car(document.querySelector('#expenseCar').value),select=document.querySelector('#expenseType');['fuel','charge','batteryRental'].forEach(type=>{const option=select.querySelector(`option[value="${type}"]`);if(option)option.disabled=type==='fuel'?!supportsFuel(c):!supportsElectric(c)})}
function render(){fillCars();renderMetrics();renderVehicleSummary();renderChart();renderReminders();renderInsuranceReminders();renderVehicleDocumentReminders();renderTables();renderReportsByPowerType();renderCars();window.orgApplyRole?.()}
function monthExpenses(){const k=today().slice(0,7);return visibleExpenses().filter(x=>x.date.startsWith(k))}
function renderMetrics(){const m=monthExpenses(),fuel=m.filter(x=>x.type==='fuel'),charge=m.filter(x=>x.type==='charge'),rental=m.filter(x=>x.type==='batteryRental'),maint=m.filter(x=>x.type==='maintenance'),total=m.reduce((s,x)=>s+x.amount,0),liters=fuel.reduce((s,x)=>s+(x.liters||0),0),energyCost=[...fuel,...charge,...rental].reduce((s,x)=>s+Number(x.amount||0),0);document.querySelector('#metrics').innerHTML=[['Tổng chi tháng này',money(total),'Tổng cộng chi phí các xe'],['Xăng / Sạc / Thuê pin',money(energyCost),liters.toFixed(1)+' lít · '+charge.length+' lần sạc · '+rental.length+' kỳ thuê pin'],['Bảo dưỡng',money(maint.reduce((s,x)=>s+x.amount,0)),maint.length+' lần']].map(x=>`<div class="card metric"><small>${x[0]}</small><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join('')}
function renderVehicleSummary(){const m=monthExpenses(),cars=[...visibleCars()].sort((a,b)=>(a.plate||'').localeCompare(b.plate||'','vi',{numeric:true})),rows=cars.map(c=>{const cost=m.filter(x=>x.carId===c.id).reduce((sum,x)=>sum+Number(x.amount||0),0);return `<tr><td><b>${esc(c.plate)}</b></td><td>${esc(c.name||'Ô tô')}</td><td><span class="tag ${supportsElectric(c)?'charge':''}">${powerTypeText(c)}</span></td><td><b>${money(cost)}</b></td><td><b>${Number(c.odo||0).toLocaleString('vi-VN')} km</b></td></tr>`});document.querySelector('#vehicleSummaryRows').innerHTML=rows.join('')||'<tr><td colspan="5" class="empty">Chưa có xe để hiển thị</td></tr>';document.querySelector('#vehicleSummaryTotal').textContent=money(m.reduce((sum,x)=>sum+Number(x.amount||0),0))}
function renderChart(){const now=new Date(),months=[];for(let i=5;i>=0;i--){let d=new Date(now.getFullYear(),now.getMonth()-i,1),k=d.toISOString().slice(0,7);months.push({k,label:'T'+(d.getMonth()+1),v:visibleExpenses().filter(x=>x.date.startsWith(k)).reduce((s,x)=>s+x.amount,0)})}const max=Math.max(...months.map(x=>x.v),1);document.querySelector('#chart').innerHTML=months.map(x=>`<div class="barwrap" title="${money(x.v)}"><div class="bar" style="height:${Math.max(2,x.v/max*85)}%"></div><span>${x.label}</span></div>`).join('')}
function addMonths(date,months){const d=new Date(date+'T00:00:00'),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+Number(months));d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));return d}
function dueItems(){const latest=new Map();visibleExpenses().filter(x=>x.type==='maintenance'&&(x.repeatKm||x.repeatMonths)).forEach(x=>{const key=x.carId+'|'+(x.description||'Bảo dưỡng').trim().toLowerCase(),old=latest.get(key);if(!old||x.date>old.date||(x.date===old.date&&Number(x.odo)>Number(old.odo)))latest.set(key,x)});const out=[];latest.forEach(x=>{const c=car(x.carId);if(!c)return;const dueOdo=x.repeatKm?Number(x.odo)+Number(x.repeatKm):null,leftKm=dueOdo===null?null:dueOdo-Number(c.odo),dueDate=x.repeatMonths?addMonths(x.date,x.repeatMonths):null,leftDays=dueDate?Math.ceil((dueDate-new Date())/86400000):null,overdueKm=leftKm!==null&&leftKm<=0,overdueDate=leftDays!==null&&leftDays<=0;out.push({...x,c,dueOdo,leftKm,dueDate,leftDays,overdueKm,overdueDate,priority:overdueKm||overdueDate?-1:Math.min(leftKm===null?999:leftKm/1500,leftDays===null?999:leftDays/45)})});return out.sort((a,b)=>a.priority-b.priority)}
function renderReminders(){const items=dueItems().slice(0,5),e=document.querySelector('#reminders');e.innerHTML=items.length?items.map(x=>{const overdue=x.overdueKm||x.overdueDate,odoPart=x.dueOdo!==null?`ở ODO ${x.dueOdo.toLocaleString('vi-VN')} km (${x.leftKm<=0?'đã vượt '+Math.abs(x.leftKm).toLocaleString('vi-VN')+' km':'còn '+x.leftKm.toLocaleString('vi-VN')+' km'})`:'',datePart=x.dueDate?`đến ngày ${x.dueDate.toLocaleDateString('vi-VN')}`:'',schedule=[odoPart,datePart].filter(Boolean).join(' hoặc '),condition=x.dueOdo!==null&&x.dueDate?' (tùy ĐK nào đến trước)':'';return `<div class="reminder reminder-action" ${expenseDetailAction(x)}><i class="dot ${overdue?'red':''}"></i><div><b>Xe có biển số: ${esc(x.c.plate)}</b><small class="maintenance-next">Kỳ bảo dưỡng tiếp theo ${schedule}${condition}</small><small>Nội dung: ${esc(x.description||'Bảo dưỡng')}</small></div></div>`}).join(''):'<div class="empty">Chưa có chu kỳ bảo dưỡng. Hãy nhập chi phí bảo dưỡng kèm chu kỳ km và số tháng.</div>'}
function insuranceItems(){const latest=new Map();visibleExpenses().filter(x=>x.type==='insurance'&&x.insuranceExpiry).forEach(x=>{const old=latest.get(x.carId);if(!old||x.insuranceExpiry>old.insuranceExpiry)latest.set(x.carId,x)});const now=new Date(today()+'T00:00:00');return [...latest.values()].map(x=>{const c=car(x.carId),expiry=new Date(x.insuranceExpiry+'T00:00:00'),days=Math.ceil((expiry-now)/86400000);return {...x,c,days}}).filter(x=>x.c).sort((a,b)=>a.days-b.days)}
function renderInsuranceReminders(){const items=insuranceItems(),e=document.querySelector('#insuranceReminders');e.innerHTML=items.length?items.map(x=>{const expired=x.days<0,warning=x.days<=45,status=expired?`⚠ ĐÃ HẾT HẠN ${Math.abs(x.days)} ngày`:x.days===0?'⚠ HẾT HẠN HÔM NAY':warning?`⚠ SẮP HẾT HẠN — còn ${x.days} ngày`:`Còn hiệu lực — còn ${x.days} ngày`,dot=expired?'red':warning?'':'green';return `<div class="insurance-reminder reminder-action ${warning?'warning':'valid'}" ${expenseDetailAction(x)}><i class="dot ${dot}"></i><div><b>Xe có biển số: ${esc(x.c.plate)}</b><small class="maintenance-next insurance-state ${warning?'warning-text':'valid-text'}">${status} — đến ngày ${dateVN(x.insuranceExpiry)}</small><small>${esc(x.insuranceProvider||'Chưa nhập đơn vị bảo hiểm')}${x.insurancePolicy?' · Số: '+esc(x.insurancePolicy):''}</small></div></div>`}).join(''):'<div class="empty">Chưa có thông tin bảo hiểm TNDS. Hãy nhập khoản bảo hiểm cho xe.</div>'}
function vehicleDocumentItems(){const latest=new Map();visibleExpenses().filter(x=>(x.type==='registration'||x.type==='roadFee')&&x.insuranceExpiry).forEach(x=>{const key=x.carId+'|'+x.type,old=latest.get(key);if(!old||x.insuranceExpiry>old.insuranceExpiry)latest.set(key,x)});const now=new Date(today()+'T00:00:00');return [...latest.values()].map(x=>{const c=car(x.carId),expiry=new Date(x.insuranceExpiry+'T00:00:00'),days=Math.ceil((expiry-now)/86400000);return {...x,c,days}}).filter(x=>x.c).sort((a,b)=>a.days-b.days)}
