function showUrgentDueAlerts(){if(urgentAlertShown)return;const lines=[];dueItems().forEach(x=>{const urgentDate=x.leftDays!==null&&x.leftDays<=5,urgentOdo=x.leftKm!==null&&x.leftKm<=0;if(!urgentDate&&!urgentOdo)return;const reason=urgentOdo?`đã đến/vượt ODO ${x.dueOdo.toLocaleString('vi-VN')} km`:`đến ngày ${x.dueDate.toLocaleDateString('vi-VN')} (${x.leftDays<0?'quá '+Math.abs(x.leftDays)+' ngày':'còn '+x.leftDays+' ngày'})`;lines.push(`• ${x.c.plate} — Bảo dưỡng: ${reason}`)});insuranceItems().filter(x=>x.days<=5).forEach(x=>lines.push(`• ${x.c.plate} — Bảo hiểm TNDS: ${x.days<0?'quá '+Math.abs(x.days)+' ngày':'còn '+x.days+' ngày'} (hạn ${dateVN(x.insuranceExpiry)})`));vehicleDocumentItems().filter(x=>x.days<=5).forEach(x=>lines.push(`• ${x.c.plate} — ${expenseTypeLabel(x.type)}: ${x.days<0?'quá '+Math.abs(x.days)+' ngày':'còn '+x.days+' ngày'} (hạn ${dateVN(x.insuranceExpiry)})`));urgentAlertShown=true;if(lines.length)alert('CẢNH BÁO CÁC HẠN TRONG 5 NGÀY\n\n'+lines.join('\n'))}
function row(x,actions=false){const c=car(x.carId)||{plate:'—'},type=expenseTypeTag(x.type),quantity=x.type==='fuel'?(x.liters||0)+' lít':x.type==='charge'?`${Number(x.batteryFrom||0).toLocaleString('vi-VN')}% → ${Number(x.batteryTo||0).toLocaleString('vi-VN')}%`:isExpiringType(x.type)?dateVN(x.insuranceExpiry):'—',attachmentCount=attachmentsOf(x).length;return `<tr class="recent-clickable" tabindex="0" role="button" aria-label="Xem chi tiết giao dịch xe ${esc(c.plate)} ngày ${dateVN(x.date)}" onclick="if(!event.target.closest('button'))showExpenseDetail('${x.id}')" onkeydown="if(event.target===this&&(event.key==='Enter'||event.key===' ')){event.preventDefault();showExpenseDetail('${x.id}')}"><td>${dateVN(x.date)}</td><td><b>${esc(c.plate)}</b></td><td>${type}</td><td>${esc(x.description||'—')}${attachmentCount?` <span title="${attachmentCount} tệp đính kèm">📎 ${attachmentCount}</span>`:''}</td><td>${Number(x.odo).toLocaleString('vi-VN')} km</td>${actions?`<td>${quantity}</td>`:''}<td><b>${money(x.amount)}</b></td>${actions?`<td>${window.orgCanEditExpense?.(x)?`<button class="btn" onclick="editExpense('${x.id}')">Sửa</button> <button class="btn danger" onclick="deleteExpense('${x.id}')">Xóa</button>`:''}</td>`:''}</tr>`}
