function fuelIntervals(){const out=[];visibleCars().filter(supportsFuel).forEach(c=>{const fills=visibleExpenses().filter(x=>x.carId===c.id&&x.type==='fuel'&&Number(x.liters)>0&&Number.isFinite(Number(x.odo))).sort((a,b)=>a.date.localeCompare(b.date)||Number(a.odo)-Number(b.odo));for(let i=1;i<fills.length;i++){const previous=fills[i-1],current=fills[i],distance=Number(current.odo)-Number(previous.odo);if(distance>0)out.push({car:c,previous,current,distance,liters:Number(current.liters),rate:Number(current.liters)/distance*100})}});return out.sort((a,b)=>b.current.date.localeCompare(a.current.date)||b.current.odo-a.current.odo)}
