function monthlyReportForCar(carId){const months={},blank=(key,odo=0)=>({key,odo,fuel:0,charge:0,batteryRental:0,maintenance:0,parts:0,insurance:0,registration:0,roadFee:0,other:0,total:0,distance:0,liters:0,chargeDistance:0,batteryRentalDistance:0});visibleExpenses().filter(x=>x.carId===carId).forEach(x=>{const key=(x.date||'').slice(0,7);if(!key)return;const m=months[key]||(months[key]=blank(key)),amount=Number(x.amount)||0,type=['fuel','charge','batteryRental','maintenance','parts','insurance','registration','roadFee','other'].includes(x.type)?x.type:'other';m[type]+=amount;m.total+=amount;m.odo=Math.max(m.odo,Number(x.odo)||0)});fuelIntervals().filter(x=>x.car.id===carId).forEach(x=>{const key=x.current.date.slice(0,7),m=months[key]||(months[key]=blank(key,Number(x.current.odo)||0));m.distance+=x.distance;m.liters+=x.liters;m.odo=Math.max(m.odo,Number(x.current.odo)||0)});electricCostIntervals().filter(x=>x.car.id===carId).forEach(x=>{const key=x.current.date.slice(0,7),m=months[key]||(months[key]=blank(key,Number(x.current.odo)||0));m[x.type+'Distance']+=x.distance;m.odo=Math.max(m.odo,Number(x.current.odo)||0)});return Object.values(months).sort((a,b)=>b.key.localeCompare(a.key))}
function excelXmlEscape(value){return String(value??'').replace(/[<>&"']/g,ch=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[ch]))}
