function excelCriteria(){const carId=document.querySelector('#reportExportCar').value,type=document.querySelector('#reportExportType').value,fromRaw=document.querySelector('#reportExportFrom').value.trim(),toRaw=document.querySelector('#reportExportTo').value.trim(),from=fromRaw?parseDateInput(fromRaw):'',to=toRaw?parseDateInput(toRaw):'';if(fromRaw&&!from){alert('Từ ngày phải nhập đúng dạng dd/mm/yyyy.');return null}if(toRaw&&!to){alert('Đến ngày phải nhập đúng dạng dd/mm/yyyy.');return null}if(from&&to&&from>to){alert('Từ ngày không được sau Đến ngày.');return null}return {carId,type,from,to}}
