const fuelDetail=showFuel?`<h3 class="fuel-detail-title">Mức tiêu hao giữa hai lần đổ xăng</h3><p class="reportnote">Toàn thời gian: ${totalDistance?`<b>${allTimeRate.toFixed(2)} L/100 km</b> · ${totalDistance.toLocaleString('vi-VN')} km · ${totalLiters.toLocaleString('vi-VN',{maximumFractionDigits:2})} lít`:'chưa đủ dữ liệu'}.</p><div class="tablewrap"><table class="table reporttable"><thead><tr><th>Lần trước</th><th>Lần sau</th><th>Quãng đường</th><th>Số lít</th><th>L/100 km</th></tr></thead><tbody>${fuelRows}</tbody></table></div>`:'';
